    author: 'ميجان فورمان (ترجمة: نبيل عبد الرحيم - بتصرّف)',
    category: 'أدبي',
    readingTimeMinutes: 6,
    wordCount: 460,
    summary: 'يوميات القبطان صالح الجابري وطاقم سفينة (جوهرة مسقط) التاريخية في الرابع عشر من إبريل 2011 وسط المحيط، حيث واجهوا عاصفة هوجاء بلغت سرعتها أكثر من 40 عقدة وأمواجاً بارتفاع 7 أمتار، وقاتلوا بروح الرجل الواحد لحماية الصاري وإنزال الشراع بشجاعة وبسالة.',
