    subtitle: 'مقال علمي معلوماتي يستعرض أبرز تقنيات الثورة الصناعية الرابعة وتطبيقاتها الذكية في حياتنا ومصانع المستقبل',
    author: 'حَاتِم فَارُوق (٢٧ مَارِس ٢٠١٧م - بِتَصَرُّفٍ)',
